import { useState } from 'react';
import { useAppProvider } from '../store';
import { User } from '../types';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { Trash } from 'lucide-react';

interface Props {
  user: User;
}

const WorkerItem: React.FC<Props> = ({ user }) => {
  const { deleteUser, currentUser, currentChurch } = useAppProvider();
  const [deleteSuccess, setDeleteSuccess] = useState<string | null>(null);

  const handleDeleteStaff = async (e: React.MouseEvent, userId: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (window.confirm('Are you sure you want to delete this staff member?')) {
      try {
        await deleteUser(userId);
        setDeleteSuccess('Staff member deleted successfully!');
        toast.success('Staff member deleted successfully!'); // Display success toast
      } catch (error) {
        toast.error('Failed to delete staff member.'); // Display error toast
      }
    }
  };

  return (
    <tr key={user.id}>
      <td className="py-2 px-4 border-b">
        {user.fullName}
      </td>
      <td className="py-2 px-4 border-b">
        {user.email}
      </td>
      <td className="py-2 px-4 border-b">
        {user.status}
      </td>
      <td className="py-2 px-4 border-b text-right">
        {user.churchRole}
      </td>
      <td className="py-2 px-4 border-b text-right">
        <button
          onClick={(e) => handleDeleteStaff(e, user.id)}
          className="text-red-500 hover:text-red-700 focus:outline-none"
        >
          <Trash size={20} />
        </button>
      </td>
    </tr>
  );
};

export default WorkerItem;
```


