  const { workers, getWorkers, currentChurch, currentUser, loading } = useAppProvider();
  const [filteredWorkers, setFilteredWorkers] = useState<User[]>([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    if (currentUser?.churchRole === 'CHURCH_ADMIN') {
      getWorkers(currentChurch?._id);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChurch, currentUser]);

  useEffect(() => {
    const filter = (search: string) => {
