import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
  User, Church, Unit, FirstTimer, AttendanceRecord, ActionPlan, 
  Announcement, Property, ChurchEvent, UserRole, Transaction, Budget, Currency 
} from './types';
import * as Mocks from './mockData';
import { auth } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

export const EXCHANGE_RATES: Record<Currency, number> = {
  [Currency.USD]: 1,
  [Currency.NGN]: 1500,
  [Currency.GBP]: 0.78
};

interface AppState {
  currentUser: User | null;
  currentChurch: Church | null;
  churches: Church[];
  users: User[];
  units: Unit[];
  firstTimers: FirstTimer[];
  attendance: AttendanceRecord[];
  tasks: ActionPlan[];
  announcements: Announcement[];
  properties: Property[];
  events: ChurchEvent[];
  transactions: Transaction[];
  budgets: Budget[];
}

interface AppContextProps extends AppState {
  login: (email: string, password?: string) => void;
  logout: () => void;
  registerUser: (user: Omit<User, 'id'>) => User;
  addChurch: (church: Omit<Church, 'id' | 'createdAt' | 'location' | 'status'>) => Church;
  setCurrentChurchId: (id: string) => void;
  updateUser: (user: Partial<User>) => void;
  approveUser: (userId: string) => void;
  deleteUser: (userId: string) => void;
  addFirstTimer: (ft: Omit<FirstTimer, 'id'>) => void;
  updateFirstTimer: (id: string, updates: Partial<FirstTimer>) => void;
  addAttendance: (record: Omit<AttendanceRecord, 'id'>) => void;
  addTask: (task: Omit<ActionPlan, 'id'>) => void;
  updateTask: (id: string, status: any) => void;
  addUnit: (unit: Omit<Unit, 'id'>) => void;
  updateUnit: (id: string, updates: Partial<Unit>) => void;
  deleteUnit: (id: string) => void;
  addProperty: (prop: Omit<Property, 'id'>) => void;
  updateProperty: (id: string, updates: Partial<Property>) => void;
  deleteProperty: (id: string) => void;
  addAnnouncement: (ann: Omit<Announcement, 'id' | 'createdAt'>) => void;
  updateAnnouncement: (id: string, updates: Partial<Announcement>) => void;
  deleteAnnouncement: (id: string) => void;
  addEvent: (event: Omit<ChurchEvent, 'id'>) => void;
  updateEvent: (id: string, updates: Partial<ChurchEvent>) => void;
  deleteEvent: (id: string) => void;
  addTransaction: (tx: Omit<Transaction, 'id'>) => void;
  addBudget: (b: Omit<Budget, 'id'>) => void;
  toggleAccountingAccess: (userId: string) => void;
  setChurchCurrency: (churchId: string, currency: Currency) => void;
  toggleChurchStatus: (churchId: string) => void;
  setCurrentUser: (user: User | null) => void;
}

const AppContext = createContext<AppContextProps | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('ecclesia_state');
    if (saved) return JSON.parse(saved);
    return {
      currentUser: null,
      currentChurch: null,
      churches: Mocks.MOCK_CHURCHES.map(c => ({ 
        ...c, 
        currency: Currency.USD,
        status: 'ACTIVE' as const,
        city: c.location.split(', ')[0] || '',
        state: c.location.split(', ')[1] || '',
        country: 'Nigeria', // Mock default
        phone: '+234 000 000 0000' // Mock default
      })),
      users: Mocks.MOCK_USERS.map(u => ({ 
        ...u, 
        password: 'password123',
        lastLogin: new Date(Date.now() - Math.random() * 86400000).toLocaleString() 
      })) as any,
      units: Mocks.MOCK_UNITS,
      firstTimers: Mocks.MOCK_FIRST_TIMERS as any,
      attendance: Mocks.MOCK_ATTENDANCE,
      tasks: Mocks.MOCK_TASKS as any,
      announcements: Mocks.MOCK_ANNOUNCEMENTS as any,
      properties: Mocks.MOCK_PROPERTIES as any,
      events: Mocks.MOCK_EVENTS as any,
      transactions: [],
      budgets: [],
    };
  });

  useEffect(() => {
    localStorage.setItem('ecclesia_state', JSON.stringify(state));
  }, [state]);

  // Sync with Firebase Auth
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
      if (firebaseUser) {
        // Find existing user in mock state or create a partial one
        const existingUser = state.users.find(u => u.email === firebaseUser.email);
        if (existingUser) {
          const church = state.churches.find(c => c.id === existingUser.churchId) || null;
          setState(prev => ({ ...prev, currentUser: existingUser, currentChurch: church }));
        } else {
          // If authenticated but not in local state (first signup), 
          // we wait for the signup process to populate users.
          // For now, if someone is logged in we create a temp profile
          const tempUser: User = {
            id: firebaseUser.uid,
            churchId: 'temp',
            fullName: firebaseUser.displayName || firebaseUser.email || 'User',
            email: firebaseUser.email || '',
            role: UserRole.CHURCH_ADMIN, // Default for new signups
            status: 'APPROVED'
          };
          setState(prev => ({ ...prev, currentUser: tempUser }));
        }
      } else {
        setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
      }
    });
    return () => unsubscribe();
  }, [state.users, state.churches]);

  const login = (email: string, password?: string) => {
    // Firebase auth is handled in Login.tsx
    // This mock function remains for local identification
    const user = state.users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (user) {
      const church = state.churches.find(c => c.id === user.churchId) || null;
      setState(prev => ({ ...prev, currentUser: user, currentChurch: church }));
    }
  };

  const logout = () => {
    signOut(auth);
    setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
  };

  const setCurrentUser = (user: User | null) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const addChurch = (churchData: Omit<Church, 'id' | 'createdAt' | 'location' | 'status'>) => {
    const newChurch: Church = {
      ...churchData,
      id: 'c-' + Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0],
      location: `${churchData.city}, ${churchData.state}`,
      currency: Currency.USD,
      status: 'ACTIVE'
    };
    setState(prev => ({
      ...prev,
      churches: [...prev.churches, newChurch]
    }));
    return newChurch;
  };

  const toggleChurchStatus = (churchId: string) => {
    setState(prev => {
      const updatedChurches = prev.churches.map(c => 
        c.id === churchId ? { ...c, status: (c.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE') as any } : c
      );

      const updatedCurrentChurch = prev.currentChurch?.id === churchId 
        ? updatedChurches.find(c => c.id === churchId) || null 
        : prev.currentChurch;

      return {
        ...prev,
        churches: updatedChurches,
        currentChurch: updatedCurrentChurch
      };
    });
  };

  const registerUser = (userData: Omit<User, 'id'>) => {
    const newUser: User = {
      ...userData,
      id: 'u-' + Math.random().toString(36).substr(2, 9),
    };
    setState(prev => ({
      ...prev,
      users: [...prev.users, newUser]
    }));
    return newUser;
  };

  const setCurrentChurchId = (id: string) => {
     const church = state.churches.find(c => c.id === id) || null;
     setState(prev => ({ ...prev, currentChurch: church }));
  }

  const approveUser = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, status: 'APPROVED' } : u)
    }));
  };

  const deleteUser = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.filter(u => u.id !== userId)
    }));
  };

  const addFirstTimer = (ft: Omit<FirstTimer, 'id'>) => {
    const newFT = { ...ft, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, firstTimers: [newFT as any, ...prev.firstTimers] }));
  };

  const updateFirstTimer = (id: string, updates: Partial<FirstTimer>) => {
    setState(prev => ({
      ...prev,
      firstTimers: prev.firstTimers.map(f => f.id === id ? { ...f, ...updates } : f)
    }));
  };

  const addAttendance = (record: Omit<AttendanceRecord, 'id'>) => {
    const newRecord = { ...record, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, attendance: [newRecord as any, ...prev.attendance] }));
  };

  const addTask = (task: Omit<ActionPlan, 'id'>) => {
    const newTask = { ...task, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, tasks: [newTask as any, ...prev.tasks] }));
  };

  const updateTask = (id: string, status: any) => {
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.map(t => t.id === id ? { ...t, status } : t)
    }));
  }

  const addUnit = (unit: Omit<Unit, 'id'>) => {
    const newUnit = { ...unit, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, units: [...prev.units, newUnit] }));
  };

  const updateUnit = (id: string, updates: Partial<Unit>) => {
    setState(prev => ({
      ...prev,
      units: prev.units.map(u => u.id === id ? { ...u, ...updates } : u)
    }));
  };

  const deleteUnit = (id: string) => {
    setState(prev => ({
      ...prev,
      units: prev.units.filter(u => u.id !== id)
    }));
  };

  const addProperty = (prop: Omit<Property, 'id'>) => {
    const newProp = { ...prop, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, properties: [...prev.properties, newProp as any] }));
  };

  const updateProperty = (id: string, updates: Partial<Property>) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProperty = (id: string) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.filter(p => p.id !== id)
    }));
  };

  const addAnnouncement = (ann: Omit<Announcement, 'id' | 'createdAt'>) => {
    const newAnn = { 
      ...ann, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0]
    };
    setState(prev => ({ ...prev, announcements: [newAnn as any, ...prev.announcements] }));
  };

  const updateAnnouncement = (id: string, updates: Partial<Announcement>) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.map(a => a.id === id ? { ...a, ...updates } : a)
    }));
  };

  const deleteAnnouncement = (id: string) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.filter(a => a.id !== id)
    }));
  };

  const addEvent = (event: Omit<ChurchEvent, 'id'>) => {
    const newEvent = { 
      ...event, 
      id: Math.random().toString(36).substr(2, 9) 
    };
    setState(prev => ({ ...prev, events: [newEvent as any, ...prev.events] }));
  };

  const updateEvent = (id: string, updates: Partial<ChurchEvent>) => {
    setState(prev => ({
      ...prev,
      events: prev.events.map(e => e.id === id ? { ...e, ...updates } : e)
    }));
  };

  const deleteEvent = (id: string) => {
    setState(prev => ({
      ...prev,
      events: prev.events.filter(e => e.id !== id)
    }));
  };

  const addTransaction = (tx: Omit<Transaction, 'id'>) => {
    const newTx = { ...tx, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ 
      ...prev, 
      transactions: [newTx as any, ...prev.transactions],
      budgets: tx.type === 'EXPENSE' 
        ? prev.budgets.map(b => b.category === tx.category ? { ...b, spentAmount: b.spentAmount + tx.amount } : b)
        : prev.budgets
    }));
  };

  const addBudget = (b: Omit<Budget, 'id'>) => {
    const newB = { ...b, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, budgets: [...prev.budgets, newB as any] }));
  };

  const toggleAccountingAccess = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, hasAccountingAccess: !u.hasAccountingAccess } : u)
    }));
  };

  const setChurchCurrency = (churchId: string, targetCurrency: Currency) => {
    setState(prev => {
      const church = prev.churches.find(c => c.id === churchId);
      if (!church) return prev;

      const sourceCurrency = church.currency || Currency.USD;
      if (sourceCurrency === targetCurrency) return prev;

      const conversionFactor = EXCHANGE_RATES[targetCurrency] / EXCHANGE_RATES[sourceCurrency];

      const updatedChurches = prev.churches.map(c => c.id === churchId ? { ...c, currency: targetCurrency } : c);
      const updatedCurrentChurch = prev.currentChurch?.id === churchId ? { ...prev.currentChurch, currency: targetCurrency } : prev.currentChurch;

      const updatedTransactions = prev.transactions.map(tx => 
        tx.churchId === churchId ? { ...tx, amount: Number((tx.amount * conversionFactor).toFixed(2)) } : tx
      );

      const updatedBudgets = prev.budgets.map(b => 
        b.churchId === churchId ? { 
          ...b, 
          allocatedAmount: Number((b.allocatedAmount * conversionFactor).toFixed(2)),
          spentAmount: Number((b.spentAmount * conversionFactor).toFixed(2))
        } : b
      );

      return {
        ...prev,
        churches: updatedChurches,
        currentChurch: updatedCurrentChurch,
        transactions: updatedTransactions,
        budgets: updatedBudgets
      };
    });
  };

  const updateUser = (user: Partial<User>) => {};

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      registerUser,
      addChurch,
      setCurrentChurchId, 
      updateUser, 
      approveUser, 
      deleteUser,
      addFirstTimer, 
      updateFirstTimer, 
      addAttendance,
      addTask,
      updateTask,
      addUnit,
      updateUnit,
      deleteUnit,
      addProperty,
      updateProperty,
      deleteProperty,
      addAnnouncement,
      updateAnnouncement,
      deleteAnnouncement,
      addEvent,
      updateEvent,
      deleteEvent,
      addTransaction,
      addBudget,
      toggleAccountingAccess,
      setChurchCurrency,
      toggleChurchStatus,
      setCurrentUser
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useApp } from '../store';
import { UserRole, User } from '../types';
import { auth } from '../firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  updateProfile
} from 'firebase/auth';

interface LoginProps {
  initialIsSignup?: boolean;
  onBackToHome?: () => void;
}

const Login: React.FC<LoginProps> = ({ initialIsSignup = false, onBackToHome }) => {
  const { registerUser, addChurch, churches, units, users, setCurrentUser } = useApp();
  const [isSignup, setIsSignup] = useState(initialIsSignup);
  const [isWorkerJoin, setIsWorkerJoin] = useState(false);
  const [targetChurchId, setTargetChurchId] = useState<string | null>(null);
  const [isPendingApproval, setIsPendingApproval] = useState(false);
  const [isChurchSuspended, setIsChurchSuspended] = useState(false);
  const [authError, setAuthError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Secret access state
  const [isSecretVisible, setIsSecretVisible] = useState(false);

  // Signup/Registration State
  const [fullName, setFullName] = useState('');
  const [phone, setPhone] = useState('');
  const [churchCity, setChurchCity] = useState('');
  const [churchState, setChurchState] = useState('');
  const [churchCountry, setChurchCountry] = useState('');
  const [newChurchName, setNewChurchName] = useState('');
  const [selectedUnitId, setSelectedUnitId] = useState('');

  // Sync isSignup with initialIsSignup prop only on mount
  useEffect(() => {
    setIsSignup(initialIsSignup);
  }, [initialIsSignup]);

  // Check for hash routes
  useEffect(() => {
    const checkHash = () => {
      const hash = window.location.hash;
      if (hash === '#platform-vault') {
        setIsSecretVisible(true);
        setIsWorkerJoin(false);
      } else if (hash.startsWith('#join-worker')) {
        const params = new URLSearchParams(hash.split('?')[1]);
        const churchId = params.get('churchId');
        if (churchId) {
          setIsWorkerJoin(true);
          setTargetChurchId(churchId);
          setIsSignup(true);
        }
      } else {
        setIsSecretVisible(false);
        setIsWorkerJoin(false);
      }
    };

    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    setLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email, password);
      // State sync is handled by onAuthStateChanged in store.tsx
    } catch (error: any) {
      console.error(error);
      setAuthError("password or email incorrect");
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);

    if (password !== confirmPassword) {
      setAuthError("Passwords do not match");
      return;
    }

    setLoading(true);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      await updateProfile(fbUser, { displayName: fullName });

      // Handle custom local state logic based on worker join or church admin
      if (isWorkerJoin && targetChurchId) {
        registerUser({
          churchId: targetChurchId,
          fullName,
          email,
          role: UserRole.WORKER,
          unitId: selectedUnitId,
          status: 'PENDING'
        });
        setIsPendingApproval(true);
      } else {
        // New church creation
        const church = addChurch({
          name: newChurchName,
          city: churchCity,
          state: churchState,
          country: churchCountry,
          phone: phone,
          adminId: fbUser.uid,
        });

        const newUser = registerUser({
          churchId: church.id,
          fullName,
          email,
          role: UserRole.CHURCH_ADMIN,
          status: 'APPROVED'
        });

        setCurrentUser(newUser);
      }
    } catch (error: any) {
      console.error(error);
      if (error.code === 'auth/email-already-in-use') {
        setAuthError("user already exist. sign in");
      } else {
        setAuthError(error.message || "An error occurred during signup");
      }
    } finally {
      setLoading(false);
    }
  };

  const targetChurch = targetChurchId ? churches.find(c => c.id === targetChurchId) : null;
  const targetUnits = targetChurchId ? units.filter(u => u.churchId === targetChurchId) : [];

  if (isChurchSuspended) {
    return (
      <div className="min-h-screen bg-rose-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10 lg:p-14 text-center animate-in zoom-in-95 duration-300">
           <div className="w-24 h-24 bg-rose-100 rounded-full flex items-center justify-center mx-auto mb-8 text-rose-600 border-4 border-rose-200">
             <span className="text-5xl">🔒</span>
           </div>
           <h2 className="text-2xl font-black text-slate-800 mb-4 tracking-tight uppercase">Account Restricted</h2>
           <p className="text-slate-500 text-sm leading-relaxed mb-8">
             Access to this church portal has been <span className="font-bold text-rose-600">suspended</span> by the platform administration. Please contact support or your organization administrator for more details.
           </p>
           <button 
             onClick={() => setIsChurchSuspended(false)}
             className="w-full bg-slate-100 text-slate-600 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all text-[10px] uppercase tracking-widest"
           >
             Return to Login
           </button>
        </div>
      </div>
    );
  }

  if (isPendingApproval) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10 lg:p-14 text-center animate-in zoom-in-95 duration-300">
           <div className="w-24 h-24 bg-amber-100 rounded-full flex items-center justify-center mx-auto mb-8">
             <span className="text-5xl">⏳</span>
           </div>
           <h2 className="text-2xl font-black text-slate-800 mb-4 tracking-tight uppercase">Approval Pending</h2>
           <p className="text-slate-500 text-sm leading-relaxed mb-8">
             Your account for <span className="font-bold text-indigo-600">{fullName || 'the church'}</span> has been created. 
             An Admin will review your registration and grant access shortly. You can login once approved using your password.
           </p>
           <button 
             onClick={() => setIsPendingApproval(false)}
             className="w-full bg-slate-100 text-slate-600 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all text-[10px] uppercase tracking-widest"
           >
             Return to Login
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4 lg:p-12 overflow-y-auto">
      <div className="bg-white rounded-[2rem] lg:rounded-[3rem] shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col my-8">
        <div className="bg-indigo-900 p-8 lg:p-12 text-center text-white relative">
          <div className="absolute top-4 left-4">
            <button 
              onClick={onBackToHome}
              className="p-2 text-white/50 hover:text-white transition-colors text-xs font-black uppercase tracking-widest"
            >
              ← Home
            </button>
          </div>
          <div className="absolute top-4 left-1/2 -translate-x-1/2 w-12 h-1.5 bg-white/20 rounded-full lg:hidden"></div>
          <h1 className="text-3xl lg:text-5xl font-black mb-2 tracking-tighter">Ecclesia</h1>
          <p className="text-indigo-200 text-sm lg:text-base opacity-80 uppercase tracking-widest font-bold">
            {isWorkerJoin ? `Join ${targetChurch?.name || 'Church'}` : isSignup ? 'Create Church Account' : 'Church Management System'}
          </p>
        </div>

        <div className="p-8 lg:p-12">
          {authError && (
            <div className="mb-6 p-4 bg-rose-50 border border-rose-100 rounded-2xl text-rose-600 text-xs font-bold text-center uppercase tracking-widest animate-in fade-in slide-in-from-top-2 duration-300">
              {authError}
            </div>
          )}

          {isSignup ? (
            <form onSubmit={handleSignup} className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="md:col-span-1">
                  <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">Full Name</label>
                  <input 
                    required
                    type="text" 
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="Enter full name"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 focus:outline-none transition-all text-sm font-bold"
                  />
                </div>
                <div className="md:col-span-1">
                  <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">Email Address</label>
                  <input 
                    required
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="you@example.com"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 focus:outline-none transition-all text-sm font-bold"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">Create Password</label>
                  <input 
                    required
                    type="password" 
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 focus:outline-none transition-all text-sm font-bold"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">Confirm Password</label>
                  <input 
                    required
                    type="password" 
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    placeholder="••••••••"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 focus:outline-none transition-all text-sm font-bold"
                  />
                </div>
              </div>

              {isWorkerJoin ? (
                <div className="space-y-5 p-5 bg-indigo-50/50 rounded-3xl border border-indigo-100 animate-in zoom-in-95 duration-300">
                  <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Worker Details</p>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Phone Number</label>
                      <input 
                        required
                        type="tel" 
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        placeholder="+234..."
                        className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Target Unit</label>
                      <select 
                        required
                        value={selectedUnitId}
                        onChange={(e) => setSelectedUnitId(e.target.value)}
                        className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                      >
                        <option value="">Select Unit</option>
                        {targetUnits.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                      </select>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-5 p-5 bg-indigo-50/50 rounded-3xl border border-indigo-100 animate-in zoom-in-95 duration-300">
                  <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Church Registry Details</p>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="md:col-span-2">
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Church Legal Name</label>
                      <input 
                        required
                        type="text" 
                        value={newChurchName}
                        onChange={(e) => setNewChurchName(e.target.value)}
                        placeholder="Grace Fellowship Center Int'l"
                        className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                      />
                    </div>

                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Official Phone</label>
                      <input 
                        required
                        type="tel" 
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        placeholder="+234 800 000 0000"
                        className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                      />
                    </div>

                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Country</label>
                      <input 
                        required
                        type="text" 
                        value={churchCountry}
                        onChange={(e) => setChurchCountry(e.target.value)}
                        placeholder="e.g. Nigeria"
                        className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                      />
                    </div>

                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">State / Province</label>
                      <input 
                        required
                        type="text" 
                        value={churchState}
                        onChange={(e) => setChurchState(e.target.value)}
                        placeholder="e.g. Lagos"
                        className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                      />
                    </div>

                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">City</label>
                      <input 
                        required
                        type="text" 
                        value={churchCity}
                        onChange={(e) => setChurchCity(e.target.value)}
                        placeholder="e.g. Ikeja"
