                  <path fill="#FBBC05" d="M12 23c3.24 0 5.96-1.07 7.95-2.91l-3.68-2.85c-1.11.75-2.52 1.19-4.27 1.19-3.16 0-5.88-2.11-6.84-5.01l-3.78 2.94C3.4 20.34 7.37 23 12 23z" />
