interface AppState {
  currentUser: User | null;
  currentChurch: Church | null;
  churches: Church[];
  users: User[];
  units: Unit[];
  firstTimers: FirstTimer[];
  attendance: AttendanceRecord[];
  tasks: ActionPlan[];
  announcements: Announcement[];
  properties: Property[];
  events: ChurchEvent[];
  transactions: Transaction[];
  budgets: Budget[];
}

interface AppContextProps extends AppState {
  login: (email: string, password?: string) => void;
  logout: () => void;
  registerUser: (user: Omit<User, 'id'>, customId?: string) => Promise<User>;
  addChurch: (church: Omit<Church, 'id' | 'createdAt' | 'location' | 'status'>) => Promise<Church>;
  setCurrentChurchId: (id: string) => void;
  updateUser: (user: Partial<User>) => Promise<void>;
  approveUser: (userId: string) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  addFirstTimer: (ft: Omit<FirstTimer, 'id'>) => Promise<void>;
  updateFirstTimer: (id: string, updates: Partial<FirstTimer>) => Promise<void>;
  addAttendance: (record: Omit<AttendanceRecord, 'id'>) => Promise<void>;
  addTask: (task: Omit<ActionPlan, 'id'>) => Promise<void>;
  updateTask: (id: string, status: any) => Promise<void>;
  addUnit: (unit: Omit<Unit, 'id'>) => Promise<void>;
  updateUnit: (id: string, updates: Partial<Unit>) => Promise<void>;
  deleteUnit: (id: string) => Promise<void>;
  addProperty: (prop: Omit<Property, 'id'>) => Promise<void>;
  updateProperty: (id: string, updates: Partial<Property>) => Promise<void>;
  deleteProperty: (id: string) => Promise<void>;
  addAnnouncement: (ann: Omit<Announcement, 'id' | 'createdAt'>) => Promise<void>;
  updateAnnouncement: (id: string, updates: Partial<Announcement>) => Promise<void>;
  deleteAnnouncement: (id: string) => Promise<void>;
  addEvent: (event: Omit<ChurchEvent, 'id'>) => Promise<void>;
  updateEvent: (id: string, updates: Partial<ChurchEvent>) => Promise<void>;
  deleteEvent: (id: string) => Promise<void>;
  addTransaction: (tx: Omit<Transaction, 'id'>) => Promise<void>;
  addBudget: (b: Omit<Budget, 'id'>) => Promise<void>;
  toggleAccountingAccess: (userId: string) => Promise<void>;
  setChurchCurrency: (churchId: string, currency: Currency) => Promise<void>;
  toggleChurchStatus: (churchId: string) => Promise<void>;
  setCurrentUser: (user: User | null) => void;
}

const AppContext = createContext<AppContextProps | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>({
    currentUser: null,
    currentChurch: null,
    churches: [],
    users: [],
    units: [],
    firstTimers: [],
    attendance: [],
    tasks: [],
    announcements: [],
    properties: [],
    events: [],
    transactions: [],
    budgets: [],
  });

  // Sync with Firebase Auth and Firestore for User Profile
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        const userRef = doc(db, 'users', firebaseUser.uid);
        const userSnap = await getDoc(userRef);

        if (userSnap.exists()) {
          const userData = userSnap.data() as User;
          // Also sync currentChurch
          const churchRef = doc(db, 'churches', userData.churchId);
          const churchSnap = await getDoc(churchRef);
          const churchData = churchSnap.exists() ? (churchSnap.data() as Church) : null;

          setState(prev => ({ ...prev, currentUser: { ...userData, id: firebaseUser.uid }, currentChurch: churchData }));

          // Update last login
          await updateDoc(userRef, { lastLogin: new Date().toLocaleString() });
        } else {
          // If user exists in Auth but not in Firestore, create the doc
          // This handles existing users or edge cases where Firestore failed during signup
          const newUser: User = {
            id: firebaseUser.uid,
            churchId: 'pending_setup',
            fullName: firebaseUser.displayName || firebaseUser.email || 'New User',
            email: firebaseUser.email || '',
            role: UserRole.CHURCH_ADMIN,
            status: 'APPROVED',
            lastLogin: new Date().toLocaleString()
          };
          await setDoc(userRef, newUser);
          setState(prev => ({ ...prev, currentUser: newUser }));
        }
      } else {
        setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
      }
    });
    return () => unsubscribe();
  }, []);

  // Real-time listeners for Church data
  useEffect(() => {
    if (!state.currentUser) return;

    const churchId = state.currentUser.churchId;
    const isPlatformOwner = state.currentUser.role === UserRole.PLATFORM_OWNER;

    const unsubscribers: (() => void)[] = [];

    const collectionsToSync = [
      { name: 'churches', stateKey: 'churches' },
      { name: 'users', stateKey: 'users' },
      { name: 'units', stateKey: 'units' },
      { name: 'firstTimers', stateKey: 'firstTimers' },
      { name: 'attendance', stateKey: 'attendance' },
      { name: 'tasks', stateKey: 'tasks' },
      { name: 'announcements', stateKey: 'announcements' },
      { name: 'properties', stateKey: 'properties' },
      { name: 'events', stateKey: 'events' },
      { name: 'transactions', stateKey: 'transactions' },
      { name: 'budgets', stateKey: 'budgets' },
    ];

    collectionsToSync.forEach(({ name, stateKey }) => {
      let q;
      // Super admins see everything, others see only their church data
      if (isPlatformOwner || name === 'churches') {
        q = query(collection(db, name));
      } else {
        q = query(collection(db, name), where('churchId', '==', churchId));
      }

      const unsub = onSnapshot(q, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
        setState(prev => ({ ...prev, [stateKey]: data }));
      });
      unsubscribers.push(unsub);
    });

    return () => unsubscribers.forEach(unsub => unsub());
  }, [state.currentUser?.churchId, state.currentUser?.role]);

  const login = (email: string, password?: string) => {
    // Auth logic is handled in Login.tsx component using Firebase Auth
  };

  const logout = () => {
    signOut(auth);
    setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
  };

  const setCurrentUser = (user: User | null) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const addChurch = async (churchData: Omit<Church, 'id' | 'createdAt' | 'location' | 'status'>) => {
    const churchId = 'c-' + Math.random().toString(36).substr(2, 9);
    const newChurch: Church = {
      ...churchData,
      id: churchId,
      createdAt: new Date().toISOString().split('T')[0],
      location: `${churchData.city}, ${churchData.state}`,
      currency: Currency.USD,
      status: 'ACTIVE'
    };
    await setDoc(doc(db, 'churches', churchId), newChurch);
    return newChurch;
  };

  const toggleChurchStatus = async (churchId: string) => {
    const churchRef = doc(db, 'churches', churchId);
    const snap = await getDoc(churchRef);
    if (snap.exists()) {
      const currentStatus = snap.data().status;
      await updateDoc(churchRef, { status: currentStatus === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE' });
    }
  };

  const registerUser = async (userData: Omit<User, 'id'>, customId?: string) => {
    const id = customId || 'u-' + Math.random().toString(36).substr(2, 9);
    const newUser: User = { ...userData, id };
    await setDoc(doc(db, 'users', id), newUser);
    return newUser;
  };

  const setCurrentChurchId = (id: string) => {
     const church = state.churches.find(c => c.id === id) || null;
     setState(prev => ({ ...prev, currentChurch: church }));
  }

  const approveUser = async (userId: string) => {
    await updateDoc(doc(db, 'users', userId), { status: 'APPROVED' });
  };

  const deleteUser = async (userId: string) => {
    await deleteDoc(doc(db, 'users', userId));
  };

  const addFirstTimer = async (ft: Omit<FirstTimer, 'id'>) => {
    await addDoc(collection(db, 'firstTimers'), ft);
  };

  const updateFirstTimer = async (id: string, updates: Partial<FirstTimer>) => {
    await updateDoc(doc(db, 'firstTimers', id), updates);
  };

  const addAttendance = async (record: Omit<AttendanceRecord, 'id'>) => {
    await addDoc(collection(db, 'attendance'), record);
  };

  const addTask = async (task: Omit<ActionPlan, 'id'>) => {
    await addDoc(collection(db, 'tasks'), task);
  };

  const updateTask = async (id: string, status: any) => {
    await updateDoc(doc(db, 'tasks', id), { status });
  }

  const addUnit = async (unit: Omit<Unit, 'id'>) => {
    await addDoc(collection(db, 'units'), unit);
  };

  const updateUnit = async (id: string, updates: Partial<Unit>) => {
    await updateDoc(doc(db, 'units', id), updates);
  };

  const deleteUnit = async (id: string) => {
    await deleteDoc(doc(db, 'units', id));
  };

  const addProperty = async (prop: Omit<Property, 'id'>) => {
    await addDoc(collection(db, 'properties'), prop);
  };

  const updateProperty = async (id: string, updates: Partial<Property>) => {
    await updateDoc(doc(db, 'properties', id), updates);
  };

  const deleteProperty = async (id: string) => {
    await deleteDoc(doc(db, 'properties', id));
  };

  const addAnnouncement = async (ann: Omit<Announcement, 'id' | 'createdAt'>) => {
    const newAnn = { 
      ...ann, 
      createdAt: new Date().toISOString().split('T')[0]
    };
    await addDoc(collection(db, 'announcements'), newAnn);
  };

  const updateAnnouncement = async (id: string, updates: Partial<Announcement>) => {
    await updateDoc(doc(db, 'announcements', id), updates);
  };

  const deleteAnnouncement = async (id: string) => {
    await deleteDoc(doc(db, 'announcements', id));
  };

  const addEvent = async (event: Omit<ChurchEvent, 'id'>) => {
    await addDoc(collection(db, 'events'), event);
  };

  const updateEvent = async (id: string, updates: Partial<ChurchEvent>) => {
    await updateDoc(doc(db, 'events', id), updates);
  };

  const deleteEvent = async (id: string) => {
    await deleteDoc(doc(db, 'events', id));
  };

  const addTransaction = async (tx: Omit<Transaction, 'id'>) => {
    await addDoc(collection(db, 'transactions'), tx);

    // Update budget spent amount if it's an expense
    if (tx.type === 'EXPENSE') {
      const bQuery = query(collection(db, 'budgets'), where('churchId', '==', tx.churchId), where('category', '==', tx.category));
      const bSnap = await getDoc(doc(db, 'budgets', tx.category)); // Simplified for demo; ideally find the doc by query
      // In a real app, you'd iterate the query results
    }
  };

  const addBudget = async (b: Omit<Budget, 'id'>) => {
    await addDoc(collection(db, 'budgets'), b);
  };

  const toggleAccountingAccess = async (userId: string) => {
    const userRef = doc(db, 'users', userId);
    const snap = await getDoc(userRef);
    if (snap.exists()) {
      await updateDoc(userRef, { hasAccountingAccess: !snap.data().hasAccountingAccess });
    }
  };

  const setChurchCurrency = async (churchId: string, targetCurrency: Currency) => {
    const churchRef = doc(db, 'churches', churchId);
    await updateDoc(churchRef, { currency: targetCurrency });
    // Note: In a production app, converting all historical amounts on currency change
    // would be a background job. For this CRM, we update the display preference.
  };

  const updateUser = async (user: Partial<User>) => {
    if (state.currentUser) {
      await updateDoc(doc(db, 'users', state.currentUser.id), user);
    }
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      registerUser,
      addChurch,
      setCurrentChurchId, 
      updateUser, 
      approveUser, 
      deleteUser,
      addFirstTimer, 
      updateFirstTimer, 
      addAttendance,
      addTask,
      updateTask,
      addUnit,
      updateUnit,
      deleteUnit,
      addProperty,
      updateProperty,
      deleteProperty,
      addAnnouncement,
      updateAnnouncement,
      deleteAnnouncement,
      addEvent,
      updateEvent,
      deleteEvent,
      addTransaction,
      addBudget,
      toggleAccountingAccess,
      setChurchCurrency,
      toggleChurchStatus,
      setCurrentUser
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../store';
import { UserRole, User } from '../types';
import { auth } from '../firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  updateProfile,
  sendEmailVerification,
  sendPasswordResetEmail,
  signOut,
  GoogleAuthProvider,
  signInWithPopup
} from 'firebase/auth';

interface LoginProps {
  initialIsSignup?: boolean;
  onBackToHome?: () => void;
}

const Login: React.FC<LoginProps> = ({ initialIsSignup = false, onBackToHome }) => {
  const { registerUser, addChurch, churches, units, users, setCurrentUser } = useApp();
  const [isSignup, setIsSignup] = useState(initialIsSignup);
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [isResetSent, setIsResetSent] = useState(false);
  const [isWorkerJoin, setIsWorkerJoin] = useState(false);
  const [targetChurchId, setTargetChurchId] = useState<string | null>(null);
  const [isPendingApproval, setIsPendingApproval] = useState(false);
  const [isChurchSuspended, setIsChurchSuspended] = useState(false);
  const [verificationEmail, setVerificationEmail] = useState<string | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Secret access state
  const [isSecretVisible, setIsSecretVisible] = useState(false);

  // Signup/Registration State
  const [fullName, setFullName] = useState('');
  const [phone, setPhone] = useState('');
  const [churchCity, setChurchCity] = useState('');
  const [churchState, setChurchState] = useState('');
  const [churchCountry, setChurchCountry] = useState('');
  const [newChurchName, setNewChurchName] = useState('');
  const [selectedUnitId, setSelectedUnitId] = useState('');

  // Sync isSignup with initialIsSignup prop only on mount
  useEffect(() => {
    setIsSignup(initialIsSignup);
  }, [initialIsSignup]);

  // Check for hash routes and invite links
  useEffect(() => {
    const checkHash = () => {
      const hash = window.location.hash;
      if (hash === '#platform-vault') {
        setIsSecretVisible(true);
        setIsWorkerJoin(false);
      } else if (hash.startsWith('#join-worker')) {
        // Robust parsing for churchId parameter
        const parts = hash.split('?');
        const queryString = parts.length > 1 ? parts[1] : '';
        const params = new URLSearchParams(queryString);
        const churchId = params.get('churchId');

        if (churchId) {
          setIsWorkerJoin(true);
          setTargetChurchId(churchId);
          setIsSignup(true);
        }
      } else {
        setIsSecretVisible(false);
        setIsWorkerJoin(false);
        setTargetChurchId(null);
      }
    };

    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  // Compute available units based on target church ID from the invite link
  const targetChurch = useMemo(() => 
    targetChurchId ? churches.find(c => c.id === targetChurchId) : null
  , [targetChurchId, churches]);

  const targetUnits = useMemo(() => 
    targetChurchId ? units.filter(u => u.churchId === targetChurchId) : []
  , [targetChurchId, units]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);
    setLoading(true);
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);

      // Check for email verification
      if (!userCredential.user.emailVerified) {
        await sendEmailVerification(userCredential.user);
        await signOut(auth);
        setVerificationEmail(email);
        setLoading(false);
        return;
      }
    } catch (error: any) {
      console.error(error);
      setAuthError("Invalid credentials. Please try again.");
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setAuthError(null);
    setLoading(true);
    const provider = new GoogleAuthProvider();
    try {
      if (isWorkerJoin && !selectedUnitId) {
        setAuthError("Please select a unit/department before joining.");
        setLoading(false);
        return;
      }

      const result = await signInWithPopup(auth, provider);
      const user = result.user;

      // Check if user exists in Firestore
      const existingUser = users.find(u => u.email === user.email);

      if (!existingUser) {
        if (isWorkerJoin && targetChurchId) {
          await registerUser({
            churchId: targetChurchId,
            fullName: user.displayName || 'Worker',
            email: user.email || '',
            role: UserRole.WORKER,
            unitId: selectedUnitId,
            status: 'PENDING'
          }, user.uid);
          setIsPendingApproval(true);
          await signOut(auth);
        } else if (isSignup) {
          const church = await addChurch({
            name: newChurchName || `${user.displayName}'s Church`,
            city: churchCity || 'Unknown',
            state: churchState || 'Unknown',
            country: churchCountry || 'Unknown',
            phone: phone || 'N/A',
            adminId: user.uid,
          });

          await registerUser({
            churchId: church.id,
            fullName: user.displayName || 'Admin',
            email: user.email || '',
            role: UserRole.CHURCH_ADMIN,
            status: 'APPROVED'
          }, user.uid);
        }
      }
    } catch (error: any) {
      console.error(error);
      setAuthError(error.message || "Social sign-in failed.");
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(null);

    if (password !== confirmPassword) {
      setAuthError("Passwords do not match");
      return;
    }

    if (isWorkerJoin && !selectedUnitId) {
      setAuthError("Selecting a unit/department is mandatory.");
      return;
    }

    setLoading(true);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      await updateProfile(fbUser, { displayName: fullName });
      await sendEmailVerification(fbUser);

      if (isWorkerJoin && targetChurchId) {
        await registerUser({
          churchId: targetChurchId,
          fullName,
          email,
          role: UserRole.WORKER,
          unitId: selectedUnitId,
          status: 'PENDING'
        }, fbUser.uid);
        setIsPendingApproval(true);
      } else {
        const church = await addChurch({
          name: newChurchName,
          city: churchCity,
          state: churchState,
          country: churchCountry,
          phone: phone,
          adminId: fbUser.uid,
        });

        await registerUser({
          churchId: church.id,
          fullName,
          email,
          role: UserRole.CHURCH_ADMIN,
          status: 'APPROVED'
        }, fbUser.uid);
      }

      await signOut(auth);
      if (!isWorkerJoin) {
        setVerificationEmail(email);
      }
    } catch (error: any) {
      console.error(error);
      if (error.code === 'auth/email-already-in-use') {
        setAuthError("An account with this email already exists.");
      } else {
        setAuthError(error.message || "Registration failed.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleForgotPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
      setAuthError("Please enter your email address first.");
      return;
    }
    setAuthError(null);
    setLoading(true);
    try {
      await sendPasswordResetEmail(auth, email);
      setIsResetSent(true);
    } catch (error: any) {
      console.error(error);
      setAuthError(error.message || "Failed to send reset email.");
    } finally {
      setLoading(false);
    }
  };

  if (isResetSent) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10 lg:p-14 text-center">
           <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 text-4xl">✓</div>
           <h2 className="text-2xl font-black text-slate-800 mb-4 uppercase tracking-tight">Email Sent</h2>
           <p className="text-slate-500 text-sm mb-8">We've sent a password reset link to <span className="font-bold text-indigo-600">{email}</span>.</p>
           <button onClick={() => { setIsResetSent(false); setIsForgotPassword(false); }} className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl uppercase tracking-widest text-xs">Return to Login</button>
        </div>
      </div>
    );
  }

  if (verificationEmail) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10 lg:p-14 text-center">
           <div className="w-20 h-20 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-8 text-4xl">✉️</div>
           <h2 className="text-2xl font-black text-slate-800 mb-4 uppercase tracking-tight">Verify Email</h2>
           <p className="text-slate-500 text-sm mb-8">Check <span className="font-bold text-indigo-600">{verificationEmail}</span> to verify your account.</p>
           <button onClick={() => setVerificationEmail(null)} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl uppercase tracking-widest text-xs">Back to Login</button>
        </div>
      </div>
    );
  }

  if (isPendingApproval) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10 lg:p-14 text-center">
           <div className="w-20 h-20 bg-amber-50 text-amber-600 rounded-full flex items-center justify-center mx-auto mb-8 text-4xl">⏳</div>
           <h2 className="text-2xl font-black text-slate-800 mb-4 uppercase tracking-tight">Request Pending</h2>
           <p className="text-slate-500 text-sm mb-8">
             Your application for <span className="font-bold text-indigo-600">{targetChurch?.name || 'the church'}</span> has been submitted. 
             An admin must approve you before you can sign in.
           </p>
           <button onClick={() => { setIsPendingApproval(false); onBackToHome?.(); }} className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl uppercase tracking-widest text-xs">Return to Home</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4 lg:p-12 overflow-y-auto">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col my-8">
        <div className="bg-indigo-900 p-8 lg:p-12 text-center text-white relative">
          <div className="absolute top-4 left-4">
            <button onClick={onBackToHome} className="text-white/50 hover:text-white text-[10px] font-black uppercase tracking-widest">← Home</button>
          </div>
          <h1 className="text-3xl lg:text-5xl font-black mb-2 tracking-tighter">Ecclesia</h1>
          <p className="text-indigo-200 text-[10px] uppercase tracking-[0.3em] font-black">
            {isWorkerJoin ? `JOIN ${targetChurch?.name || 'CHURCH'}` : isSignup ? 'CREATE ACCOUNT' : isForgotPassword ? 'SECURITY RESET' : 'CHURCH MANAGEMENT'}
          </p>
        </div>

        <div className="p-8 lg:p-12">
          {authError && (
            <div className="mb-6 p-4 bg-rose-50 border border-rose-100 rounded-2xl text-rose-600 text-[10px] font-black text-center uppercase tracking-widest animate-in fade-in duration-300">
              {authError}
            </div>
          )}

          {isForgotPassword ? (
            <form onSubmit={handleForgotPassword} className="space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest">Email Address</label>
                <input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="your@email.com" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-sm font-bold transition-all" />
              </div>
              <button disabled={loading} className="w-full bg-indigo-600 text-white font-black py-5 rounded-2xl uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 disabled:opacity-50">Send Reset Link</button>
              <div className="text-center pt-4">
                <button type="button" onClick={() => setIsForgotPassword(false)} className="text-[10px] font-black text-slate-500 hover:text-indigo-600 uppercase">Back to Login</button>
              </div>
            </form>
          ) : isSignup ? (
            <form onSubmit={handleSignup} className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase">Full Name</label>
                  <input required type="text" value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="e.g. David King" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-sm font-bold" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase">Email</label>
                  <input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-sm font-bold" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase">Password</label>
                  <input required type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-sm font-bold" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase">Confirm Password</label>
                  <input required type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="••••••••" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-sm font-bold" />
                </div>
              </div>

              {isWorkerJoin ? (
                <div className="space-y-4 p-5 bg-indigo-50/50 rounded-3xl border border-indigo-100">
                  <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Staff Registration Details</p>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Phone Number</label>
                      <input required type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+234..." className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Target Unit/Department</label>
                      <select required value={selectedUnitId} onChange={(e) => setSelectedUnitId(e.target.value)} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold cursor-pointer hover:border-indigo-400 transition-colors">
                        <option value="">-- Choose Unit --</option>
                        {targetUnits.length > 0 ? (
                          targetUnits.map(u => <option key={u.id} value={u.id}>{u.name}</option>)
                        ) : (
                          <option value="GENERAL">General Registry</option>
                        )}
                      </select>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-4 p-5 bg-indigo-50/50 rounded-3xl border border-indigo-100">
                  <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Church Information</p>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="md:col-span-2">
