const AppContent: React.FC = () => {
  const { currentUser, currentChurch } = useApp();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [viewState, setViewState] = useState<'LANDING' | 'AUTH' | 'PRICING'>('LANDING');
  const [initialSignupMode, setInitialSignupMode] = useState(false);

  React.useEffect(() => {
    if (window.location.hash.startsWith('#join-worker')) setViewState('AUTH');
  }, []);

  if (!currentUser) {
    if (viewState === 'LANDING') return <Home onGetStarted={() => { setInitialSignupMode(true); setViewState('AUTH'); }} onLogin={() => { setInitialSignupMode(false); setViewState('AUTH'); }} onViewPricing={() => setViewState('PRICING')} />;
    if (viewState === 'PRICING') return <Pricing onBack={() => setViewState('LANDING')} onGetStarted={() => { setInitialSignupMode(true); setViewState('AUTH'); }} />;
    return <Login initialIsSignup={initialSignupMode} onBackToHome={() => setViewState('LANDING')} />;
  }

  if (currentUser.status === 'PENDING') return <PendingApprovalScreen />;
  if (currentChurch?.status === 'SUSPENDED' && currentUser.role !== UserRole.PLATFORM_OWNER) return <SuspendedScreen />;

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'first-timers': return <FirstTimers />;
      case 'attendance': return <Attendance />;
      case 'superadmin': return <SuperAdmin />;
      case 'tasks': return <ActionPlans />;
      case 'units': return <Units />;
      case 'inventory': return <Properties />;
      case 'announcements': return <Announcements />;
      case 'events': return <Events />;
      case 'accounting': return <Accounting />;
      case 'workers': return <Workers />;
      default: return <Dashboard />;
    }
  };

  return <Layout activeTab={activeTab} setActiveTab={setActiveTab}>{renderContent()}</Layout>;
};

const App: React.FC = () => <AppProvider><AppContent /></AppProvider>;
export default App;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
  User, Church, Unit, FirstTimer, AttendanceRecord, ActionPlan, 
  Announcement, Property, ChurchEvent, UserRole, Transaction, Budget, Currency 
} from './types';
import { auth, db } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { 
  doc, 
  setDoc, 
  getDoc, 
  collection, 
  onSnapshot, 
  query, 
  where, 
  updateDoc, 
  deleteDoc, 
  addDoc 
} from 'firebase/firestore';

export const EXCHANGE_RATES: Record<Currency, number> = {
  [Currency.USD]: 1,
  [Currency.NGN]: 1500,
  [Currency.GBP]: 0.78
};

interface AppState {
  currentUser: User | null;
  currentChurch: Church | null;
  churches: Church[];
  users: User[];
  units: Unit[];
  firstTimers: FirstTimer[];
  attendance: AttendanceRecord[];
  tasks: ActionPlan[];
  announcements: Announcement[];
  properties: Property[];
  events: ChurchEvent[];
  transactions: Transaction[];
  budgets: Budget[];
}

interface AppContextProps extends AppState {
  login: (email: string, password?: string) => void;
  logout: () => void;
  registerUser: (user: Omit<User, 'id'>, customId?: string) => Promise<User>;
  addChurch: (church: Omit<Church, 'id' | 'createdAt' | 'location' | 'status'>) => Promise<Church>;
  setCurrentChurchId: (id: string) => void;
  updateUser: (user: Partial<User>) => Promise<void>;
  approveUser: (userId: string) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  addFirstTimer: (ft: Omit<FirstTimer, 'id'>) => Promise<void>;
  updateFirstTimer: (id: string, updates: Partial<FirstTimer>) => Promise<void>;
  addAttendance: (record: Omit<AttendanceRecord, 'id'>) => Promise<void>;
  addTask: (task: Omit<ActionPlan, 'id'>) => Promise<void>;
  updateTask: (id: string, status: any) => Promise<void>;
  addUnit: (unit: Omit<Unit, 'id'>) => Promise<void>;
  updateUnit: (id: string, updates: Partial<Unit>) => Promise<void>;
  deleteUnit: (id: string) => Promise<void>;
  addProperty: (prop: Omit<Property, 'id'>) => Promise<void>;
  updateProperty: (id: string, updates: Partial<Property>) => Promise<void>;
  deleteProperty: (id: string) => Promise<void>;
  addAnnouncement: (ann: Omit<Announcement, 'id' | 'createdAt'>) => Promise<void>;
  updateAnnouncement: (id: string, updates: Partial<Announcement>) => Promise<void>;
  deleteAnnouncement: (id: string) => Promise<void>;
  addEvent: (event: Omit<ChurchEvent, 'id'>) => Promise<void>;
  updateEvent: (id: string, updates: Partial<ChurchEvent>) => Promise<void>;
  deleteEvent: (id: string) => Promise<void>;
  addTransaction: (tx: Omit<Transaction, 'id'>) => Promise<void>;
  addBudget: (b: Omit<Budget, 'id'>) => Promise<void>;
  toggleAccountingAccess: (userId: string) => Promise<void>;
  setChurchCurrency: (churchId: string, currency: Currency) => Promise<void>;
  toggleChurchStatus: (churchId: string) => Promise<void>;
  setCurrentUser: (user: User | null) => void;
}

const AppContext = createContext<AppContextProps | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>({
    currentUser: null,
    currentChurch: null,
    churches: [],
    users: [],
    units: [],
    firstTimers: [],
    attendance: [],
    tasks: [],
    announcements: [],
    properties: [],
    events: [],
    transactions: [],
    budgets: [],
  });

  // Sync with Firebase Auth and Firestore for User Profile
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser && firebaseUser.emailVerified) {
        try {
          const userRef = doc(db, 'users', firebaseUser.uid);
          const userSnap = await getDoc(userRef);

          if (userSnap.exists()) {
            const userData = userSnap.data() as User;
            let churchData = null;

            if (userData.churchId && userData.churchId !== 'pending_setup') {
              const churchRef = doc(db, 'churches', userData.churchId);
              const churchSnap = await getDoc(churchRef);
              churchData = churchSnap.exists() ? (churchSnap.data() as Church) : null;
            }

            setState(prev => ({ 
              ...prev, 
              currentUser: { ...userData, id: firebaseUser.uid }, 
              currentChurch: churchData 
            }));

            await updateDoc(userRef, { lastLogin: new Date().toLocaleString() });
          } else {
            const newUser: User = {
              id: firebaseUser.uid,
              churchId: 'pending_setup',
              fullName: firebaseUser.displayName || firebaseUser.email || 'New User',
              email: firebaseUser.email || '',
              role: UserRole.CHURCH_ADMIN,
              status: 'APPROVED',
              lastLogin: new Date().toLocaleString(),
              hasAccountingAccess: false
            };
            await setDoc(userRef, newUser);
            setState(prev => ({ ...prev, currentUser: newUser }));
          }
        } catch (error) {
          console.error("Error syncing user data:", error);
        }
      } else {
        setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
      }
    });
    return () => unsubscribe();
  }, []);

  // Real-time listeners for data syncing
  useEffect(() => {
    if (!state.currentUser) return;

    const churchId = state.currentUser.churchId;
    const isPlatformOwner = state.currentUser.role === UserRole.PLATFORM_OWNER;
    const unsubscribers: (() => void)[] = [];

    const collectionsToSync = [
      { name: 'churches', stateKey: 'churches' },
      { name: 'users', stateKey: 'users' },
      { name: 'units', stateKey: 'units' },
      { name: 'firstTimers', stateKey: 'firstTimers' },
      { name: 'attendance', stateKey: 'attendance' },
      { name: 'tasks', stateKey: 'tasks' },
      { name: 'announcements', stateKey: 'announcements' },
      { name: 'properties', stateKey: 'properties' },
      { name: 'events', stateKey: 'events' },
      { name: 'transactions', stateKey: 'transactions' },
      { name: 'budgets', stateKey: 'budgets' },
    ];

    collectionsToSync.forEach(({ name, stateKey }) => {
      let q;
      if (isPlatformOwner || name === 'churches') {
        q = query(collection(db, name));
      } else {
        q = query(collection(db, name), where('churchId', '==', churchId));
      }

      const unsub = onSnapshot(q, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
        setState(prev => ({ ...prev, [stateKey]: data }));
      }, (error) => {
        console.error(`Error syncing ${name}:`, error);
      });
      unsubscribers.push(unsub);
    });

    return () => unsubscribers.forEach(unsub => unsub());
  }, [state.currentUser?.churchId, state.currentUser?.role]);

  const login = (email: string, password?: string) => { };

  const logout = () => {
    signOut(auth);
    setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
  };

  const setCurrentUser = (user: User | null) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const addChurch = async (churchData: Omit<Church, 'id' | 'createdAt' | 'location' | 'status'>) => {
    const churchId = 'c-' + Math.random().toString(36).substr(2, 9);
    const newChurch: Church = {
      ...churchData,
      id: churchId,
      createdAt: new Date().toISOString().split('T')[0],
      location: `${churchData.city}, ${churchData.state}`,
      currency: Currency.USD,
      status: 'ACTIVE'
    };
    await setDoc(doc(db, 'churches', churchId), newChurch);
    return newChurch;
  };

  const toggleChurchStatus = async (churchId: string) => {
    const churchRef = doc(db, 'churches', churchId);
    const snap = await getDoc(churchRef);
    if (snap.exists()) {
      await updateDoc(churchRef, { status: snap.data().status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE' });
    }
  };

  const registerUser = async (userData: Omit<User, 'id'>, customId?: string) => {
    const id = customId || 'u-' + Math.random().toString(36).substr(2, 9);
    const newUser: User = { ...userData, id };
    await setDoc(doc(db, 'users', id), newUser);
    return newUser;
  };

  const setCurrentChurchId = (id: string) => {
     const church = state.churches.find(c => c.id === id) || null;
     setState(prev => ({ ...prev, currentChurch: church }));
  };

  const approveUser = async (userId: string) => {
    await updateDoc(doc(db, 'users', userId), { status: 'APPROVED' });
  };

  const deleteUser = async (userId: string) => {
    await deleteDoc(doc(db, 'users', userId));
  };

  const addFirstTimer = async (ft: Omit<FirstTimer, 'id'>) => {
    await addDoc(collection(db, 'firstTimers'), ft);
  };

  const updateFirstTimer = async (id: string, updates: Partial<FirstTimer>) => {
    await updateDoc(doc(db, 'firstTimers', id), updates);
  };

  const addAttendance = async (record: Omit<AttendanceRecord, 'id'>) => {
    await addDoc(collection(db, 'attendance'), record);
  };

  const addTask = async (task: Omit<ActionPlan, 'id'>) => {
    await addDoc(collection(db, 'tasks'), task);
  };

  const updateTask = async (id: string, status: any) => {
    await updateDoc(doc(db, 'tasks', id), { status });
  };

  const addUnit = async (unit: Omit<Unit, 'id'>) => {
    await addDoc(collection(db, 'units'), unit);
  };

  const updateUnit = async (id: string, updates: Partial<Unit>) => {
    await updateDoc(doc(db, 'units', id), updates);
  };

  const deleteUnit = async (id: string) => {
    await deleteDoc(doc(db, 'units', id));
  };

  const addProperty = async (prop: Omit<Property, 'id'>) => {
    await addDoc(collection(db, 'properties'), prop);
  };

  const updateProperty = async (id: string, updates: Partial<Property>) => {
    await updateDoc(doc(db, 'properties', id), updates);
  };

  const deleteProperty = async (id: string) => {
    await deleteDoc(doc(db, 'properties', id));
  };

  const addAnnouncement = async (ann: Omit<Announcement, 'id' | 'createdAt'>) => {
    await addDoc(collection(db, 'announcements'), { ...ann, createdAt: new Date().toISOString().split('T')[0] });
  };

  const updateAnnouncement = async (id: string, updates: Partial<Announcement>) => {
    await updateDoc(doc(db, 'announcements', id), updates);
  };

  const deleteAnnouncement = async (id: string) => {
    await deleteDoc(doc(db, 'announcements', id));
  };

  const addEvent = async (event: Omit<ChurchEvent, 'id'>) => {
    await addDoc(collection(db, 'events'), event);
  };

  const updateEvent = async (id: string, updates: Partial<ChurchEvent>) => {
    await updateDoc(doc(db, 'events', id), updates);
  };

  const deleteEvent = async (id: string) => {
    await deleteDoc(doc(db, 'events', id));
  };

  const addTransaction = async (tx: Omit<Transaction, 'id'>) => {
    await addDoc(collection(db, 'transactions'), tx);
  };

  const addBudget = async (b: Omit<Budget, 'id'>) => {
    await addDoc(collection(db, 'budgets'), b);
  };

  const toggleAccountingAccess = async (userId: string) => {
    const userRef = doc(db, 'users', userId);
    const snap = await getDoc(userRef);
    if (snap.exists()) {
      await updateDoc(userRef, { hasAccountingAccess: !snap.data().hasAccountingAccess });
    }
  };

  const setChurchCurrency = async (churchId: string, currency: Currency) => {
    await updateDoc(doc(db, 'churches', churchId), { currency });
  };

  const updateUser = async (user: Partial<User>) => {
    if (state.currentUser) {
      await updateDoc(doc(db, 'users', state.currentUser.id), user);
    }
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      registerUser,
      addChurch,
      setCurrentChurchId, 
