                      <input 
                        type="checkbox" 
                        name="headIds" 
                        value={user.id}
                        defaultChecked={editingUnit?.headIds.includes(user.id)}
                        className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500" 
                      />
