            >
              <option value="ALL">All Departments</option>
              {units.filter(u => u.churchId === currentUser?.churchId).map(u => (
                <option key={u.id} value={u.id}>{u.name}</option>
              ))}
            </select>
          )}
        </div>

        {/* Desktop View Table */}
        <div className="hidden md:block overflow-x-auto">
