                  {editingProp ? 'Confirm Changes' : 'Record Asset'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Properties;

import React, { useState } from 'react';
import { useApp } from '../store.tsx';
import { UserRole, Announcement, Unit } from '../types.ts';

const Announcements: React.FC = () => {
  const { announcements, units, currentUser, addAnnouncement, deleteAnnouncement } = useApp();
  const [showAddModal, setShowAddModal] = useState(false);
  const [filter, setFilter] = useState<'ALL' | 'GLOBAL' | 'UNIT'>('ALL');

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const isUnitHead = currentUser?.role === UserRole.UNIT_HEAD;
  const canPost = isAdmin || isUnitHead;

  const churchAnns = announcements.filter(a => a.churchId === currentUser?.churchId);
  const filteredAnns = churchAnns.filter(a => {
    const isGlobal = !a.unitId;
    const isForMyUnit = a.unitId === currentUser?.unitId;

    // Visibility logic: Admins see everything, others see global + their unit
    const isVisible = isAdmin || isGlobal || isForMyUnit;
    if (!isVisible) return false;

    if (filter === 'GLOBAL') return isGlobal;
    if (filter === 'UNIT') return !isGlobal;
    return true;
  });

  const handleCreate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const title = formData.get('title') as string;
    const body = formData.get('body') as string;
    const unitId = formData.get('unitId') as string;
    const expiryDate = formData.get('expiryDate') as string;

    addAnnouncement({
      churchId: currentUser!.churchId,
      title,
      body,
      unitId: unitId === 'GLOBAL' ? undefined : unitId,
      expiryDate: expiryDate || undefined
    });
    setShowAddModal(false);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h3 className="text-2xl font-bold text-slate-800">Announcements</h3>
          <p className="text-slate-500">Stay informed about church updates and unit news</p>
        </div>
        {canPost && (
          <button 
            onClick={() => setShowAddModal(true)}
            className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 font-semibold flex items-center gap-2 w-fit"
          >
            <span className="text-xl">📢</span> Post Announcement
          </button>
        )}
      </div>

      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit">
        {(['ALL', 'GLOBAL', 'UNIT'] as const).map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${filter === f ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
          >
            {f === 'ALL' ? 'All Updates' : f === 'GLOBAL' ? 'Global' : 'Unit News'}
          </button>
        ))}
      </div>

      <div className="space-y-6">
        {filteredAnns.map((ann) => (
          <div key={ann.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm p-8 relative overflow-hidden group">
            {!ann.unitId ? (
              <div className="absolute top-0 right-0 px-4 py-1 bg-indigo-100 text-indigo-700 text-[10px] font-black uppercase rounded-bl-xl">Global</div>
            ) : (
              <div className="absolute top-0 right-0 px-4 py-1 bg-emerald-100 text-emerald-700 text-[10px] font-black uppercase rounded-bl-xl">
                {units.find(u => u.id === ann.unitId)?.name || 'Unit'}
              </div>
            )}

            <div className="flex justify-between items-start mb-4">
              <div>
                <h4 className="text-xl font-black text-slate-800 mb-1 leading-tight">{ann.title}</h4>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{ann.createdAt}</p>
              </div>
              {isAdmin || (isUnitHead && ann.unitId === currentUser?.unitId) ? (
                <button 
                  onClick={() => deleteAnnouncement(ann.id)}
                  className="text-slate-300 hover:text-rose-600 p-2 transition-colors opacity-0 group-hover:opacity-100"
                >
                  🗑️
                </button>
              ) : null}
            </div>

            <div className="text-slate-600 leading-relaxed whitespace-pre-wrap mb-6">
              {ann.body}
            </div>

            {ann.expiryDate && (
              <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 italic pt-4 border-t border-slate-50">
                <span>⏳ Valid until:</span>
                <span>{ann.expiryDate}</span>
              </div>
            )}
          </div>
        ))}

        {filteredAnns.length === 0 && (
          <div className="py-24 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
            <div className="text-5xl mb-4">📭</div>
            <p className="text-slate-500 font-bold">No announcements to show.</p>
            <p className="text-xs text-slate-400 mt-1">Check back later for updates!</p>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-xl p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">Broadcast Message</h2>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-600 text-xl">✕</button>
            </div>

            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Announcement Title</label>
                <input required name="title" type="text" placeholder="e.g., Upcoming Thanksgiving Service" className="w-full border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none border bg-slate-50" />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Message Body</label>
                <textarea required name="body" rows={5} placeholder="Type your announcement here..." className="w-full border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none border bg-slate-50"></textarea>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Target Audience</label>
                  <select name="unitId" required className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-500">
                    {isAdmin && <option value="GLOBAL">Entire Church</option>}
                    {isAdmin ? (
                      units.filter(u => u.churchId === currentUser?.churchId).map(u => (
                        <option key={u.id} value={u.id}>Unit: {u.name}</option>
                      ))
                    ) : (
                      <option value={currentUser?.unitId}>My Unit: {units.find(u => u.id === currentUser?.unitId)?.name}</option>
                    )}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Expiry Date (Optional)</label>
                  <input name="expiryDate" type="date" className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
              </div>

              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-6 py-3 border border-slate-200 text-slate-600 rounded-xl hover:bg-slate-50 font-bold">Cancel</button>
                <button type="submit" className="flex-1 px-6 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold shadow-lg shadow-indigo-100">Post Announcement</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Announcements;

import React, { useState } from 'react';
import { useApp } from '../store.tsx';
import { UserRole, ChurchEvent } from '../types.ts';

const Events: React.FC = () => {
  const { events, currentUser, addEvent, updateEvent, deleteEvent } = useApp();
  const [view, setView] = useState<'LIST' | 'CALENDAR'>('LIST');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingEvent, setEditingEvent] = useState<ChurchEvent | null>(null);

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const isUnitHead = currentUser?.role === UserRole.UNIT_HEAD;
  const canManage = isAdmin || isUnitHead;

  const churchEvents = events.filter(e => e.churchId === currentUser?.churchId);
  const sortedEvents = [...churchEvents].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  // Calendar Logic
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());

  const daysInMonth = (month: number, year: number) => new Date(year, month + 1, 0).getDate();
  const startDayOfMonth = (month: number, year: number) => new Date(year, month, 1).getDay();

  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const handlePrevMonth = () => {
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
  };

  const handleNextMonth = () => {
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
  };

  const handleCreateOrUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const title = formData.get('title') as string;
    const date = formData.get('date') as string;
    const location = formData.get('location') as string;
    const description = formData.get('description') as string;

    if (editingEvent) {
      updateEvent(editingEvent.id, { title, date, location, description });
    } else {
      addEvent({
        churchId: currentUser!.churchId,
        title,
        date,
        location,
        description
      });
    }
    setShowAddModal(false);
    setEditingEvent(null);
  };

  return (
    <div className="space-y-6 lg:space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h3 className="text-xl lg:text-2xl font-bold text-slate-800">Events & Calendar</h3>
          <p className="text-sm text-slate-500">Scheduled activities and special services</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="bg-white p-1 rounded-xl border border-slate-200 flex shadow-sm grow md:grow-0">
            <button 
              onClick={() => setView('LIST')}
              className={`flex-1 md:flex-none px-4 py-2 rounded-lg text-[10px] lg:text-xs font-black transition-all ${view === 'LIST' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              List View
            </button>
            <button 
              onClick={() => setView('CALENDAR')}
              className={`flex-1 md:flex-none px-4 py-2 rounded-lg text-[10px] lg:text-xs font-black transition-all ${view === 'CALENDAR' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Calendar
            </button>
          </div>
          {canManage && (
            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white p-2.5 lg:px-6 lg:py-2.5 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 font-semibold flex items-center justify-center gap-2"
            >
              <span className="text-xl">+</span> <span className="hidden lg:inline">Add Event</span>
            </button>
          )}
        </div>
      </div>

      {view === 'LIST' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 lg:gap-6">
          {sortedEvents.map(event => (
            <div key={event.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm p-5 lg:p-6 group hover:border-indigo-300 transition-all flex flex-col">
              <div className="flex justify-between items-start mb-4">
                <div className="bg-indigo-50 text-indigo-600 p-2.5 lg:p-3 rounded-2xl">
                   <span className="text-lg lg:text-xl">📅</span>
                </div>
                {canManage && (
                  <div className="flex gap-1 lg:gap-2">
                    <button 
                      onClick={() => {
                        setEditingEvent(event);
                        setShowAddModal(true);
                      }}
                      className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                    >
                      ✏️
                    </button>
                    <button 
                      onClick={() => {
                        if (confirm('Cancel this event?')) deleteEvent(event.id);
                      }}
                      className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                    >
                      🗑️
                    </button>
                  </div>
                )}
              </div>

              <h4 className="text-base lg:text-lg font-bold text-slate-800 mb-2 truncate">{event.title}</h4>
              <p className="text-xs lg:text-sm text-slate-500 mb-6 flex-1 line-clamp-3">{event.description}</p>

              <div className="space-y-2 pt-4 border-t border-slate-50">
                <div className="flex items-center gap-2 text-[10px] lg:text-xs text-slate-600">
                  <span className="opacity-60 shrink-0">🕒</span>
                  <span className="font-semibold truncate">{event.date}</span>
                </div>
                <div className="flex items-center gap-2 text-[10px] lg:text-xs text-slate-600">
                  <span className="opacity-60 shrink-0">📍</span>
                  <span className="font-semibold truncate">{event.location}</span>
                </div>
              </div>
            </div>
          ))}
          {sortedEvents.length === 0 && (
            <div className="col-span-full py-20 lg:py-24 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
               <span className="text-4xl lg:text-5xl mb-4 block">🏜️</span>
               <p className="text-slate-500 font-bold text-sm lg:text-base">No upcoming events found.</p>
            </div>
          )}
        </div>
      ) : (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden p-4 lg:p-8">
          <div className="flex flex-col sm:flex-row items-center justify-between mb-8 gap-4">
            <h4 className="text-lg lg:text-xl font-black text-slate-800">{monthNames[currentMonth]} {currentYear}</h4>
            <div className="flex gap-2 w-full sm:w-auto">
              <button onClick={handlePrevMonth} className="flex-1 sm:flex-none p-2 hover:bg-slate-100 rounded-lg border border-slate-100 sm:border-none">◀</button>
              <button onClick={() => { setCurrentMonth(today.getMonth()); setCurrentYear(today.getFullYear()); }} className="flex-1 sm:flex-none px-4 py-2 text-[10px] font-bold text-indigo-600 bg-indigo-50 rounded-lg">Today</button>
              <button onClick={handleNextMonth} className="flex-1 sm:flex-none p-2 hover:bg-slate-100 rounded-lg border border-slate-100 sm:border-none">▶</button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-1 lg:gap-4 overflow-x-auto min-w-[300px]">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map(day => (
              <div key={day} className="text-center text-[8px] lg:text-[10px] font-black uppercase tracking-widest text-slate-400 pb-2 lg:pb-4 shrink-0">{day}</div>
            ))}

            {Array.from({ length: startDayOfMonth(currentMonth, currentYear) }).map((_, i) => (
              <div key={`empty-${i}`} className="aspect-square shrink-0"></div>
            ))}

            {Array.from({ length: daysInMonth(currentMonth, currentYear) }).map((_, i) => {
              const dayNum = i + 1;
              const dateString = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
              const dayEvents = churchEvents.filter(e => e.date.startsWith(dateString));
              const isToday = today.getDate() === dayNum && today.getMonth() === currentMonth && today.getFullYear() === currentYear;

              return (
                <div key={dayNum} className={`aspect-square border border-slate-50 rounded-lg lg:rounded-2xl flex flex-col items-center justify-center relative transition-colors cursor-default shrink-0 ${isToday ? 'bg-indigo-600 text-white' : 'hover:bg-indigo-50/50'}`}>
                  <span className={`text-[10px] lg:text-sm font-bold ${isToday ? '' : 'text-slate-700'}`}>{dayNum}</span>
                  {dayEvents.length > 0 && (
                    <div className="flex gap-0.5 mt-0.5 lg:mt-1">
                      {dayEvents.slice(0, 3).map(e => (
                        <div key={e.id} className={`w-0.5 h-0.5 lg:w-1 lg:h-1 rounded-full ${isToday ? 'bg-white' : 'bg-indigo-500'}`}></div>
                      ))}
                    </div>
                  )}
                  {dayEvents.length > 0 && (
                     <div className="absolute inset-0 opacity-0 lg:hover:opacity-100 bg-white/95 backdrop-blur-sm p-1 lg:p-2 rounded-lg lg:rounded-2xl flex flex-col justify-center items-center text-[8px] lg:text-[10px] text-slate-800 transition-opacity z-10 border border-indigo-100 pointer-events-none lg:pointer-events-auto">
                        {dayEvents.slice(0, 2).map(e => <p key={e.id} className="truncate w-full text-center font-bold">· {e.title}</p>)}
                        {dayEvents.length > 2 && <p className="font-black text-indigo-600 text-[6px] mt-0.5">+{dayEvents.length - 2} MORE</p>}
                     </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Add/Edit Event Modal */}
      {(showAddModal || editingEvent) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[70] p-4">
          <div className="bg-white rounded-[2rem] lg:rounded-[3rem] w-full max-w-xl p-6 lg:p-10 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl lg:text-3xl font-black text-slate-800 tracking-tight">
                {editingEvent ? 'Edit Event' : 'Schedule Event'}
              </h2>
              <button 
                onClick={() => {
                  setShowAddModal(false);
                  setEditingEvent(null);
                }} 
                className="text-slate-400 hover:text-slate-600 text-xl p-2"
              >✕</button>
            </div>

            <form onSubmit={handleCreateOrUpdate} className="space-y-5 lg:space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Event Title</label>
                <input 
                  required 
                  name="title" 
                  defaultValue={editingEvent?.title}
                  placeholder="e.g., Annual Harvest Thanksgiving" 
                  className="w-full border-slate-200 rounded-2xl p-4 focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 focus:outline-none border bg-slate-50 text-sm font-bold" 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div>
                  <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Date</label>
                  <input 
                    required 
                    name="date" 
                    type="date"
                    defaultValue={editingEvent?.date || new Date().toISOString().split('T')[0]}
                    className="w-full border-slate-200 rounded-2xl p-4 focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 focus:outline-none border bg-slate-50 text-sm font-bold" 
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Location</label>
                  <input 
                    required 
                    name="location" 
                    defaultValue={editingEvent?.location}
                    placeholder="Main Sanctuary..." 
                    className="w-full border-slate-200 rounded-2xl p-4 focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 focus:outline-none border bg-slate-50 text-sm font-bold" 
                  />
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Event Description</label>
                <textarea 
                  required 
                  name="description" 
                  rows={4}
                  defaultValue={editingEvent?.description}
                  placeholder="Details about the service or activity..." 
                  className="w-full border-slate-200 rounded-2xl p-4 focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 focus:outline-none border bg-slate-50 text-sm font-medium" 
                ></textarea>
              </div>

              <div className="flex flex-col sm:flex-row gap-4 pt-6">
                <button 
                  type="button" 
                  onClick={() => {
                    setShowAddModal(false);
                    setEditingEvent(null);
                  }} 
                  className="flex-1 px-8 py-4 border border-slate-200 text-slate-600 rounded-2xl hover:bg-slate-50 font-black text-xs uppercase tracking-widest transition-all"
                >Cancel</button>
                <button 
                  type="submit" 
                  className="flex-1 px-8 py-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-100 transition-all"
                >
                  {editingEvent ? 'Update Event' : 'Create Event'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Events;

import React, { useState } from 'react';
import { useApp, EXCHANGE_RATES } from '../store.tsx';
import { UserRole, Transaction, Budget, Currency } from '../types.ts';

const Accounting: React.FC = () => {
  const { 
    transactions, budgets, currentUser, users, currentChurch,
    addTransaction, addBudget, toggleAccountingAccess, setChurchCurrency 
  } = useApp();

  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'BUDGETS' | 'PERMISSIONS'>('OVERVIEW');
  const [showTxModal, setShowTxModal] = useState(false);
  const [showBudgetModal, setShowBudgetModal] = useState(false);
  const [converting, setConverting] = useState(false);

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const currencySymbol = currentChurch?.currency || Currency.USD;

  const churchTx = transactions.filter(t => t.churchId === currentUser?.churchId);
  const churchBudgets = budgets.filter(b => b.churchId === currentUser?.churchId);
  const churchWorkers = users.filter(u => u.churchId === currentUser?.churchId && u.role === UserRole.WORKER && u.status === 'APPROVED');

  const totalIncome = churchTx.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = churchTx.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const handleAddTx = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addTransaction({
      churchId: currentUser!.churchId,
      type: formData.get('type') as 'INCOME' | 'EXPENSE',
      category: formData.get('category') as string,
      amount: parseFloat(formData.get('amount') as string),
      date: formData.get('date') as string,
      description: formData.get('description') as string,
      recordedBy: currentUser!.id
    });
    setShowTxModal(false);
  };

  const handleAddBudget = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addBudget({
      churchId: currentUser!.churchId,
      category: formData.get('category') as string,
      allocatedAmount: parseFloat(formData.get('amount') as string),
      spentAmount: 0,
      period: formData.get('period') as string
    });
    setShowBudgetModal(false);
  };

  const handleCurrencyChange = (newCurrency: Currency) => {
    if (currentChurch && currentChurch.currency !== newCurrency) {
      setConverting(true);
      setTimeout(() => {
        setChurchCurrency(currentChurch.id, newCurrency);
        setConverting(false);
      }, 600);
    }
  };

  return (
    <div className="space-y-6 lg:space-y-10 pb-20 relative px-1 sm:px-0">
      {converting && (
        <div className="fixed inset-0 bg-white/90 backdrop-blur-md z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
           <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-6"></div>
           <p className="text-indigo-950 font-black text-sm uppercase tracking-[0.3em] px-8 text-center leading-relaxed">Syncing Financial Vault...</p>
        </div>
      )}

      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="space-y-1">
          <h3 className="text-2xl lg:text-5xl font-black text-slate-900 tracking-tighter leading-tight">Financial Treasury</h3>
          <p className="text-xs lg:text-base text-slate-500 font-medium max-w-md">Overseeing the stewardship of church assets.</p>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
          <div className="bg-slate-100 p-1 rounded-2xl border border-slate-200 flex items-center">
            {[Currency.USD, Currency.NGN, Currency.GBP].map(curr => (
              <button
                key={curr}
                onClick={() => handleCurrencyChange(curr)}
                className={`flex-1 sm:flex-none px-4 py-2 rounded-xl text-[10px] font-black transition-all ${currencySymbol === curr ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
              >
                {curr}
              </button>
            ))}
          </div>
          <button 
            onClick={() => setShowTxModal(true)}
            className="bg-indigo-600 text-white px-6 py-4 rounded-2xl hover:bg-indigo-700 transition shadow-xl shadow-indigo-100 font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-2 active:scale-95"
          >
            <span className="text-lg">💰</span> Add Entry
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="overflow-x-auto pb-2 -mx-4 px-4 sm:mx-0 sm:px-0 no-scrollbar">
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-max min-w-full sm:min-w-0">
          {(['OVERVIEW', 'TRANSACTIONS', 'BUDGETS', 'PERMISSIONS'] as const).map((t) => (
            (t === 'PERMISSIONS' && !isAdmin) ? null : (
              <button
                key={t}
                onClick={() => setActiveTab(t)}
                className={`px-4 lg:px-8 py-3 rounded-xl text-[9px] lg:text-xs font-black transition-all whitespace-nowrap tracking-widest uppercase ${activeTab === t ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {t}
              </button>
            )
          ))}
        </div>
      </div>

      {activeTab === 'OVERVIEW' && (
        <div className="space-y-6 lg:space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-500">
          {/* Key Metrics */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 lg:gap-6">
            <div className="bg-slate-900 p-6 lg:p-12 rounded-[2rem] lg:rounded-[3rem] text-white shadow-2xl relative overflow-hidden group">
              <div className="absolute -top-4 -right-4 p-8 opacity-10 text-8xl italic font-black group-hover:scale-110 transition-transform duration-1000 select-none">
                {currencySymbol}
              </div>
              <p className="text-indigo-400 font-black uppercase tracking-widest text-[9px] mb-4">Net Balance</p>
              <h2 className="text-3xl lg:text-5xl font-black tracking-tighter truncate leading-tight">
                {currencySymbol}{balance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </h2>
            </div>
            <div className="bg-white p-6 lg:p-10 rounded-[2rem] lg:rounded-[3rem] border border-slate-200 shadow-sm flex flex-col justify-center">
              <p className="text-emerald-500 font-black uppercase tracking-widest text-[9px] mb-2">Total Inflow</p>
              <h2 className="text-2xl lg:text-3xl font-black text-emerald-600 tracking-tighter truncate">
                +{currencySymbol}{totalIncome.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </h2>
            </div>
            <div className="bg-white p-6 lg:p-10 rounded-[2rem] lg:rounded-[3rem] border border-slate-200 shadow-sm flex flex-col justify-center">
              <p className="text-rose-500 font-black uppercase tracking-widest text-[9px] mb-2">Total Outflow</p>
              <h2 className="text-2xl lg:text-3xl font-black text-rose-600 tracking-tighter truncate">
                -{currencySymbol}{totalExpense.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </h2>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-10">
            {/* Budgets Panel */}
            <div className="bg-white p-6 lg:p-10 rounded-[2.5rem] lg:rounded-[3.5rem] border border-slate-200 shadow-sm">
              <div className="flex justify-between items-center mb-8">
                <div>
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Budgets</h4>
                </div>
                <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center font-bold text-xl">📊</div>
              </div>
              <div className="space-y-8">
                {churchBudgets.map(b => {
                  const percent = b.allocatedAmount > 0 ? Math.min((b.spentAmount / b.allocatedAmount) * 100, 100) : 0;
                  const isOver = b.spentAmount > b.allocatedAmount;
                  return (
                    <div key={b.id} className="space-y-3">
                      <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-tight">
                        <span className="text-slate-800">{b.category}</span>
                        <span className={isOver ? 'text-rose-600' : 'text-slate-500'}>
                          {Math.round(percent)}% Used
                        </span>
                      </div>
                      <div className="h-3 bg-slate-100 rounded-full overflow-hidden shadow-inner">
                        <div 
                          className={`h-full transition-all duration-700 rounded-full ${isOver ? 'bg-rose-500' : 'bg-indigo-600'}`} 
                          style={{ width: `${percent}%` }}
                        ></div>
                      </div>
                    </div>
                  );
                })}
                {churchBudgets.length === 0 && (
                  <div className="text-center py-10 text-slate-400 text-xs italic">No active budgets.</div>
                )}
              </div>
            </div>

            {/* Recent History Panel */}
            <div className="bg-white p-6 lg:p-10 rounded-[2.5rem] lg:rounded-[3.5rem] border border-slate-200 shadow-sm">
              <div className="flex justify-between items-center mb-8">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Recent Activity</h4>
                <button onClick={() => setActiveTab('TRANSACTIONS')} className="text-[9px] font-black text-indigo-600 uppercase tracking-widest hover:underline">View All</button>
              </div>
              <div className="space-y-4">
                {churchTx.slice(0, 4).map(tx => (
                  <div key={tx.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex items-center gap-4 min-w-0">
                      <div className={`w-10 h-10 rounded-xl shrink-0 flex items-center justify-center font-black text-sm ${tx.type === 'INCOME' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                        {tx.type === 'INCOME' ? '↓' : '↑'}
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-slate-900 truncate leading-none mb-1">{tx.description}</p>
                        <p className="text-[8px] text-slate-400 font-bold uppercase">{tx.date}</p>
                      </div>
                    </div>
